// ai-agents/orchestrator/src/activities/noise.ts: sketch, not final code. Activities may use the clock; workflows may not.
import { Gate } from "@rhinohealth/ai-agents-shared";

const IDLE_MS = 7 * 24 * 60 * 60 * 1000;  // 7 days

export async function mayOpenPr(routine: string, repo: string): Promise<Gate> {
  const openPrs = await broker.github.searchPrs(repo, { labels: [`routine:${routine}`], state: "open" });
  if (openPrs.length) {  // one open PR per routine; the run waits, it doesn't open a second one
    return Gate.wait(`${routine} already has #${openPrs[0].number} open`);
  }
  return Gate.go({ labels: [`routine:${routine}`, "agent"], draft: true });  // always a draft first
}

export async function closeIdlePrs(repo: string): Promise<number[]> {
  const closed: number[] = [];
  for (const pr of await broker.github.searchPrs(repo, { labelPrefix: "routine:", state: "open" })) {
    if (Date.now() - pr.lastActivityAt.getTime() < IDLE_MS) continue;  // commits, comments and reviews all count
    await broker.github.comment(pr.number, "Closing: no activity for 7 days. Reopen it to pick it up again.");
    await broker.github.close(pr.number);
    await broker.jira.comment(pr.jiraKey, `Routine PR #${pr.number} was closed after 7 idle days.`);
    closed.push(pr.number);
  }
  return closed;
}

// ai-agents/orchestrator/src/activities/digest.ts: sketch
const WINDOW = 20, MIN_MERGED = 0.5;

export async function mergeRate(routine: string, repo: string): Promise<number | undefined> {
  const closed = await broker.github.searchPrs(repo, { labels: [`routine:${routine}`], state: "closed",
                                                      sort: "closed", limit: WINDOW });
  if (closed.length < WINDOW) {
    return undefined;  // not enough data: never pause on a few PRs
  }
  return closed.filter((pr) => pr.merged).length / WINDOW;
}

export async function autoPause(routine: Routine): Promise<string | undefined> {
  const rate = await mergeRate(routine.name, routine.repo);
  if (rate === undefined || rate >= MIN_MERGED) {
    return undefined;
  }
  const reason = `only ${Math.round(rate * 100)}% of its last ${WINDOW} PRs were merged`;
  await flags.set(`routine:${routine.name}:paused`, reason);  // G3 flag store, checked before every run
  await slack.dm(routine.owner, `${routine.name} is paused: ${reason}.`, { buttons: ["Resume", "Keep paused"] });
  return reason;
}

export async function postTeamDigest(team: string): Promise<void> {
  const items = await collectDigest(team);  // ready PRs, drafts per owner, idle closes, pauses, cost per routine
  if (items.empty) {
    return;  // a quiet day sends nothing
  }
  await slack.post(people.channel(team), renderDigest(team, items));
}

// ai-agents/orchestrator/src/routines/ladder.ts: sketch; a daily schedule calls evaluate() for every routine
const STAGES = ["shadow", "drafts", "normal"] as const;
const pct = (x: number): string => `${Math.round(x * 100)}%`;
export function demotionReason(s: RoutineStats): string | undefined {
  if (s.falseHealsSinceStageChange) return "a false heal";
  if (s.revertedPrsWithin14Days.length) return `#${s.revertedPrsWithin14Days[0]} was reverted within 14 days`;
  if (s.mergeRate !== undefined && s.mergeRate < 0.5) {  // mergeRate() from G5-03, last 20 PRs
    return `only ${pct(s.mergeRate)} of its last 20 PRs merged`;
  }
  return undefined;
}

export function missingForPromotion(s: RoutineStats, bench: SliceScore): string[] {
  const missing: string[] = [];
  if (bench.solvedRate < 0.5) missing.push(`bench slice solved ${pct(bench.solvedRate)}, needs 50%`);
  if (s.kind === "bug-fixer" && bench.reproduceRate < 0.6) {
    missing.push(`reproduced ${pct(bench.reproduceRate)} of bugs, needs 60%`);
  }
  if (s.falseHealsTotal || bench.falseHeals) missing.push("has false heals");
  if (s.runsAtStage < 10) missing.push(`only ${s.runsAtStage} runs at this stage`);  // a starting value; set it from data
  return missing;
}

export async function evaluate(routine: Routine): Promise<void> {
  const [s, bench] = await Promise.all([stats(routine), latestBench(routine)]);  // bench scores from the G1 eval store
  const stage = STAGES.indexOf(routine.effectiveStage);
  const why = demotionReason(s);
  if (why && stage > 0) {
    await flags.set(`routine:${routine.name}:stage_override`, STAGES[stage - 1], { reason: why });  // takes effect now
    await openCharterPr(routine, STAGES[stage - 1], why);  // the file catches up through review
    await slack.dm(routine.owner, `${routine.name} moved back to ${STAGES[stage - 1]}: ${why}`);
  } else if (stage < 2 && missingForPromotion(s, bench).length === 0) {
    await slack.dm(routine.owner, `${routine.name} qualifies for ${STAGES[stage + 1]}. Open the charter PR if you agree.`);
  }
}

// ai-agents/orchestrator/src/reports/shadow-report.ts: sketch; the Sunday schedule calls it
const RUBRIC = `You compare two fixes for the same failure. Answer in JSON with keys
same_root_cause (yes/no/unsure), size (smaller/similar/bigger), reviewer_would_reject (yes/no), why (one line).
Judge the routine's fix on its own merits: a different fix can still be right.`;

export async function weeklyShadowReport(since: Date): Promise<Row[]> {
  const rows: Row[] = [];
  for (const run of await shadowRuns(since)) {  // Stage = 'shadow' AND CloseTime > since
    const human = await findHumanFix(run);  // next green on main, the linked PR, or what the Renovate PR became
    if (!human) {
      rows.push({ run, human: undefined, note: "no human fix yet" });
      continue;
    }
    let tests: TestRun | undefined;
    if (human.addedTests.length) {  // the objective answer: do the human's tests pass on our diff?
      tests = await runOnLiteVm({ base: run.baseSha, patch: run.diffS3Key, tests: human.addedTests });
    }
    const verdict = await judge({ model: "claude-sonnet-5-5", effort: "medium", system: RUBRIC,
                                  inputs: { failure: run.triggerSummary, routine_fix: run.diff, human_fix: human.diff } });
    rows.push({ run, human: human.url, tests, verdict, cost: run.costUsd });
  }
  await postToWeeklyReview(renderTable(rows));  // one thread in the weekly run review, not team channels
  return rows;
}
